// Subgraph as a node: mapped inputs, namespaced outputs (plain JS pattern)
function asSubgraph(graph, mapIn, mapOut) {
  return (parentState) => {
    const childState = mapIn(parentState);          // parent -> child contract
    const result = runGraph(graph.nodes, graph.edges, childState);
    return mapOut(result.state, parentState);       // child -> parent contract
  };
}
